import{_ as e,a,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Workflows","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/index.md","filePath":"api/workflows/index.md","lastUpdated":1787290888000}'),i={name:"api/workflows/index.md"};function n(s,t,d,l,h,p){return o(),a("div",null,t[0]||(t[0]=[r('<h1 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h1><p>A workflow is the ordered sequence of Bagisto API calls a client fires to complete a feature — and which call depends on which. Each page shows the dependency flow as a diagram, then links the endpoint page backing every step. Bagisto has no server-side workflow primitive; &quot;workflow&quot; here means the client call-sequence, framework-agnostic.</p><h2 id="how-to-read-a-workflow-page" tabindex="-1">How to read a workflow page <a class="header-anchor" href="#how-to-read-a-workflow-page" aria-label="Permalink to &quot;How to read a workflow page&quot;">​</a></h2><p>Every flow page uses the same blocks:</p><ol><li><strong>Agent-ask inputs</strong> — values the agent must ask you for. Today that is the <strong>server URL</strong> and the <strong>storefront key</strong>.</li><li><strong>Prerequisites</strong> — what must exist first (key, cart token, auth).</li><li><strong>Dependency diagram</strong> — a Mermaid flow you can follow top to bottom.</li><li><strong>Ordered call table</strong> — step, endpoint (linked), what it depends on.</li><li><strong>End-to-end example</strong> — the happy path, REST and GraphQL.</li><li><strong>Customize</strong> — link to extend the flow.</li></ol><h2 id="shop" tabindex="-1">Shop <a class="header-anchor" href="#shop" aria-label="Permalink to &quot;Shop&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>What it builds</th></tr></thead><tbody><tr><td><a href="/api/workflows/shop/build-a-storefront.html">Build a Storefront</a></td><td>Catalog, cart, and checkout end to end</td></tr><tr><td><a href="/api/workflows/shop/cart.html">Cart</a></td><td>Guest/customer cart, add/update items, coupons, merge on login</td></tr><tr><td><a href="/api/workflows/shop/checkout.html">Checkout</a></td><td>Addresses, shipping, payment methods, place order</td></tr></tbody></table><h2 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>What it builds</th></tr></thead><tbody><tr><td><a href="/api/workflows/admin/build-an-admin-dashboard.html">Build an Admin Dashboard</a></td><td>The complete blueprint — every admin menu mapped to its API</td></tr><tr><td><a href="/api/workflows/admin/create-order-flow.html">Create-Order Flow</a></td><td>Placing an order for a customer (sequential draft-cart state machine)</td></tr><tr><td><a href="/api/workflows/admin/product-management.html">Product Management</a></td><td>Create/edit products — 7 types, two-step create, image/inventory/price panels</td></tr><tr><td><a href="/api/workflows/admin/order-fulfillment-actions.html">Order Fulfillment Actions</a></td><td>Invoice, ship, refund, cancel — per-order eligibility guards</td></tr><tr><td><a href="/api/workflows/admin/customers.html">Customers (Impersonate &amp; GDPR)</a></td><td>Impersonation token and GDPR delete/download flows</td></tr><tr><td><a href="/api/workflows/admin/marketing.html">Marketing</a></td><td>Promotions, communications, search &amp; SEO — rule reindex, campaigns, coupons, sitemaps</td></tr><tr><td><a href="/api/workflows/admin/configuration.html">Configuration</a></td><td>Slug-scoped store settings via three generic endpoints</td></tr></tbody></table><h2 id="customization" tabindex="-1">Customization <a class="header-anchor" href="#customization" aria-label="Permalink to &quot;Customization&quot;">​</a></h2><p>Extending the API itself (adding or changing endpoints) — see <a href="/api/workflows/customization/">Customization</a>.</p><p>Every call below links to its <strong>REST</strong> endpoint page for concreteness. The sequence is transport-agnostic — the same flow works over GraphQL with the equivalent query or mutation, and each REST page cross-links to its GraphQL twin. Pick whichever transport your client uses; only the request shape changes, never the order of steps.</p><div class="tip custom-block"><p class="custom-block-title">Building with an AI agent?</p><p>See <a href="/api/build-with-ai/">Build with AI</a> for the <code>llms.txt</code> index, the agent skills, and the optional docs MCP server.</p></div>',13)]))}const f=e(i,[["render",n]]);export{m as __pageData,f as default};
